/// Returns a two-element vector `[off, coeff]` where:
/// - The first element is exactly `off`.
/// - The second element is `0.0` if `scl` is zero (this also canonicalizes `-0.0` to `+0.0`),
///   otherwise it is exactly `scl`.
pub fn hermeline(off: f64, scl: f64) -> Vec<f64> {
    let coeff = if scl == 0.0 { 0.0 } else { scl };
    vec![off, coeff]
}

#[cfg(test)]
mod tests {
    use super::hermeline;

    #[test]
    fn test_nonzero() {
        let v = hermeline(1.23, 4.56);
        assert_eq!(v, vec![1.23, 4.56]);
    }

    #[test]
    fn test_zero() {
        let v = hermeline(-7.89, 0.0);
        assert_eq!(v, vec![-7.89, 0.0]);
    }

    #[test]
    fn test_negative_zero() {
        let neg_zero = -0.0_f64;
        assert_eq!(neg_zero, 0.0); // equality check treats -0.0 == 0.0
        let v = hermeline(3.14, neg_zero);
        // We expect +0.0 in the result
        assert_eq!(v, vec![3.14, 0.0]);
        assert!(v[1].is_sign_positive()); // confirms it's +0.0
    }

    #[test]
    fn test_nan() {
        let v = hermeline(0.0, f64::NAN);
        assert!(v[1].is_nan());
    }

    #[test]
    fn test_infinite() {
        let v = hermeline(2.0, f64::INFINITY);
        assert_eq!(v, vec![2.0, f64::INFINITY]);
    }
}